import type { SegmentedButtonProps } from "./segmented-button.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "SegmentedButton";

// Generate child element class names for the component, should match available style slots
export const SegmentedButtonClasses = {
  root: "exp-textura_segmented-button",
  sm: "exp-textura_segmented-button_sm",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    root: {
      backgroundColor: theme.buttonSegmented.critical.color.background,
      borderColor: theme.buttonSegmented.critical.color.border,
    },
  },
  inverse: {
    root: {
      backgroundColor: theme.buttonSegmented.inverse.color.background,
      borderColor: theme.buttonSegmented.inverse.color.border,
    },
  },
});

const generateStyles = (props: SegmentedButtonProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<SegmentedButtonProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    flexWrap: "inherit",
    flexDirection: "row",
    width: "fit-content",
    backgroundColor: theme.buttonSegmented.default.color.background,
    border: `${theme.buttonSegmented.border.width} solid ${theme.buttonSegmented.default.color.border}`,
    borderRadius: theme.buttonSegmented.border.radius,
    padding: `${theme.toRem(1)}`,
    gap: `${theme.toRem(2)}`,

    "& > button": {
      height: theme.toRem(28),
      ...styleSlots?.button,
    },

    "& > button[data-last-selected='true']": {
      cursor: "default",
    },

    [`&.${SegmentedButtonClasses.sm}`]: {
      height: theme.toRem(24),
      "& > button": {
        height: theme.toRem(20),
        ...styleSlots?.buttonSm,
      },
      ...styleSlots?.sm,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps("isLastSelected");

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledSegmentedButton = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<SegmentedButtonProps>((props) => generateStyles(props));
